import re

_UNIT_SECONDS = {
    's': 1, 'sec': 1, 'secs': 1, 'second': 1, 'seconds': 1,
    'm': 60, 'min': 60, 'mins': 60, 'minute': 60, 'minutes': 60,
    'h': 3600, 'hr': 3600, 'hrs': 3600, 'hour': 3600, 'hours': 3600,
    'd': 86400, 'day': 86400, 'days': 86400,
    'w': 604800, 'wk': 604800, 'wks': 604800, 'week': 604800, 'weeks': 604800,
}

_ISO_RE = re.compile(
    r'^P(?:(?P<weeks>\d+(?:\.\d+)?)W)?'
    r'(?:(?P<days>\d+(?:\.\d+)?)D)?'
    r'(?:T(?:(?P<hours>\d+(?:\.\d+)?)H)?'
    r'(?:(?P<minutes>\d+(?:\.\d+)?)M)?'
    r'(?:(?P<seconds>\d+(?:\.\d+)?)S)?)?$',
    re.IGNORECASE,
)

_COMPONENT_RE = re.compile(r'(\d+(?:\.\d+)?)\s*([a-zA-Z]+)')


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if text is None:
        raise ValueError("empty duration")

    original = text
    text = text.strip()
    if not text:
        raise ValueError("empty duration")

    # bare integer
    if re.fullmatch(r'\d+', text):
        return int(text)

    # ISO 8601 duration
    if text[0] in 'Pp':
        m = _ISO_RE.match(text)
        if not m or not any(m.groupdict().values()):
            raise ValueError(f"invalid ISO duration: {original!r}")
        total = 0.0
        groups = m.groupdict()
        unit_seconds = {
            'weeks': 604800,
            'days': 86400,
            'hours': 3600,
            'minutes': 60,
            'seconds': 1,
        }
        for key, value in groups.items():
            if value is not None:
                total += float(value) * unit_seconds[key]
        return round(total)

    # clock notation
    if ':' in text:
        parts = text.split(':')
        if len(parts) not in (2, 3):
            raise ValueError(f"invalid clock duration: {original!r}")
        for p in parts:
            if not re.fullmatch(r'\d+(?:\.\d+)?', p):
                raise ValueError(f"invalid clock duration: {original!r}")
        values = [float(p) for p in parts]
        if len(values) == 2:
            minutes, seconds = values
            total = minutes * 60 + seconds
        else:
            hours, minutes, seconds = values
            total = hours * 3600 + minutes * 60 + seconds
        return round(total)

    # unit components, e.g. "1h30m", "1 hour 30 minutes"
    pos = 0
    total = 0.0
    found_any = False
    length = len(text)
    while pos < length:
        while pos < length and text[pos].isspace():
            pos += 1
        if pos >= length:
            break
        m = _COMPONENT_RE.match(text, pos)
        if not m:
            raise ValueError(f"invalid duration: {original!r}")
        number_str, unit = m.groups()
        unit_key = unit.lower()
        if unit_key not in _UNIT_SECONDS:
            raise ValueError(f"unknown unit {unit!r} in {original!r}")
        total += float(number_str) * _UNIT_SECONDS[unit_key]
        found_any = True
        pos = m.end()

    if not found_any:
        raise ValueError(f"invalid duration: {original!r}")

    return round(total)

